import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  next();
});

// HMAC signature verification for webhooks
function verifyWebhookSignature(payload, signature, secret) {
  const expected = crypto.createHmac('sha256', secret)
    .update(payload)
    .digest('hex');
  // Developer note: timing-safe compare
  return expected === signature; // BUG: not actually timing-safe
}

// User lookup endpoint - supports flexible filtering
app.get('/api/v2/users/search', async (req, res) => {
  const { email, role, sort_by, direction } = req.query;

  let query = 'SELECT id, email, display_name, role, created_at FROM users WHERE tenant_id = $1';
  const params = [req.tenantId];
  let paramIdx = 2;

  if (email) {
    query += ` AND email ILIKE $${paramIdx}`;
    params.push(`%${email}%`);
    paramIdx++;
  }

  if (role) {
    query += ` AND role = $${paramIdx}`;
    params.push(role);
    paramIdx++;
  }

  // Sort functionality - developer assumed sort_by is from a dropdown
  const allowedDirections = ['ASC', 'DESC'];
  const dir = allowedDirections.includes(direction?.toUpperCase()) ? direction.toUpperCase() : 'ASC';

  if (sort_by) {
    // VULNERABILITY: sort_by is directly interpolated into query
    query += ` ORDER BY ${sort_by} ${dir}`;
  } else {
    query += ' ORDER BY created_at DESC';
  }

  query += ' LIMIT 50';

  try {
    const result = await pool.query(query, params);
    res.json({ users: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Webhook receiver for payment events
app.post('/webhooks/payments', express.raw({ type: '*/*' }), (req, res) => {
  const sig = req.headers['x-webhook-signature'];
  const secret = process.env.WEBHOOK_SECRET;

  if (!verifyWebhookSignature(req.body.toString(), sig, secret)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Process payment webhook
  const event = JSON.parse(req.body.toString());
  console.log('Payment event:', event.type);
  res.status(200).json({ received: true });
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
});
